function [out,kernsd] = mySmooth(x, N, varargin)
% operates on first dimension only - make sure first dim is time
% gaussian kernel with window size N
% varargin:
%   'reflect' - reflect N elements from beginning of time series across
%               0 index
%   'zeropad' - pad N zeros across 0 index
%   'none'    - don't handle boundary conditions

% returns:
% - out: filtered data, same size as x
% - kernsd: std dev of gaussian kernel

% % example usage:
% x = 5*sin(1:0.01:100)';
% y = x + randn(size(x));
% N = 51;
% out = mySmooth(y,N,'reflect');
% 
% figure;
% subplot(3,1,1); plot(x);
% xlim([-100 200])
% subplot(3,1,2); plot(y)
% xlim([-100 200])
% subplot(3,1,3); plot(out); %hold on; plot(out,'.','MarkerSize',6)
% xlim([-100 200])


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

if N == 0 || N == 1 % no smoothing
    out = x;
    kernsd = 0;
    return
end

if isrow(x) % if 1-d time series, ensure column vector
    x = x';
end

if nargin > 2
    % handle a boundary condition
    bctype = varargin{1};
    if strcmpi(bctype,'reflect')
        x_filt = cat(1,x(1:N,:),x);
        trim = N + 1;
    elseif strcmpi(bctype,'zeropad')
        x_filt = cat(1,zeros(N,size(x,2)),x);
        trim = N + 1;
    elseif strcmpi(bctype,'none')
        x_filt = x;
        trim = 1;
    else
        warning('invalid boundary condition type - regular smoothing');
        x_filt = x;
        trim = 1;
    end
else
    % no bc handling
    x_filt = x;
    trim = 1;
end



Ncol = size(x_filt, 2);
Nel = size(x_filt, 1);

kern = gausswin(N);
kernsd = std(1:N);


kern(1:floor(numel(kern)/2)) = 0; %causal
kern = kern./sum(kern);

out = zeros(Nel, Ncol);
for j = 1:Ncol
    out(:, j) = conv(x_filt(:, j), kern, 'same');
end
out = out(trim:end,:);

end=====
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% Figure 8a-c -- Finding CDContext from neural activity that resides within the Null and Potent spaces
% Then finding selectivity between CDContext from full neural pop and
% CDContext found from null/potent reconstructions
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
clear,clc,close all
%% Set paths

% Base path for where code lives
basepth = 'C:\Code';

% add paths
utilspth = [basepth '\Uninstructed-Movements\For sharing'];
addpath(genpath(fullfile(utilspth,'DataLoadingScripts')));
addpath(genpath(fullfile(utilspth,'funcs')));
addpath(genpath(fullfile(utilspth,'Utils')));
%% PARAMETERS
params.alignEvent          = 'goCue'; % 'jawOnset' 'goCue'  'moveOnset'  'firstLick'  'lastLick'

params.timeWarp            = 0;  % piecewise linear time warping - each lick duration on each trial gets warped to median lick duration for that lick across trials
params.nLicks              = 20; % number of post go cue licks to calculate median lick duration for and warp individual trials to

params.lowFR               = 1; % remove clusters with firing rates across all trials less than this val

% set conditions to calculate PSTHs for
params.condition(1)     = {'(hit|miss|no)'};                             % all trials
params.condition(end+1) = {'hit&~stim.enable&~autowater'};               % all 2AFC hits, no stim
params.condition(end+1) = {'hit&~stim.enable&autowater'};                % all AW hits, no stim
params.condition(end+1) = {'miss&~stim.enable&~autowater'};              % error 2AFC, no stim, aw off
params.condition(end+1) = {'miss&~stim.enable&autowater'};               % error AW, no stim

params.condition(end+1) = {'hit&~stim.enable&~autowater&~early'};               % all 2AFC hits, ~early, no stim
params.condition(end+1) = {'hit&~stim.enable&autowater&~early'};                % all AW hits, ~early,no stim

params.tmin = -3;       % min time (in s) relative to alignEvent 
params.tmax = 2.5;      % max time (in s) relative to alignEvent 
params.dt = 1/100;      % bin size (s)

% smooth with causal gaussian kernel
params.smooth = 15;

% Sorted unit qualities to use (can specify whether you only want to use
% single units or multi units)
params.quality = {'all'}; % accepts any cell array of strings - special character 'all' returns clusters of any quality

% Kinematic features that you want to load
params.traj_features = {{'tongue','left_tongue','right_tongue','jaw','trident','nose'},...
    {'top_tongue','topleft_tongue','bottom_tongue','bottomleft_tongue','jaw','top_nostril','bottom_nostril'}};

params.feat_varToExplain = 80; % num factors for dim reduction of video features should explain this much variance

params.N_varToExplain = 80; % keep num dims that explains this much variance in neural data (when doing n/p)

params.advance_movement = 0;

params.bctype = 'reflect'; % options are : reflect  zeropad  none
%% SPECIFY DATA TO LOAD

datapth = 'C:\Users\Jackie Birnbaum\Documents\Data';

